// behaviour: the component's model owns the state machine
public final class ToggleModel extends DefaultButtonModel {
    @Override public void setPressed(boolean p) { /* transitions live here */ }
}
// markup: the UI delegate paints from the model
public class FlatToggleUI extends BasicToggleButtonUI {
    @Override public void paint(Graphics g, JComponent c) {
        AbstractButton b = (AbstractButton) c;                 // state from the component
        g.setColor(b.getModel().isSelected() ? on : off);
        g.fillRoundRect(0, 0, b.getWidth(), b.getHeight(), 8, 8);
    }
}

