public class DisclosureSkin implements Skin<Disclosure> {   // consumer's visuals
    private final Disclosure control;
    private final VBox root = new VBox();
    public DisclosureSkin(Disclosure c) { this.control = c; install(); }
    @Override public Disclosure getSkinnable() { return control; }
    @Override public Node getNode() { return root; }
    @Override public void dispose() { /* undo listeners and bindings */ }
}
